def bubble_sort(lst: list) -> list:
    n = len(lst)
    lst = lst.copy()
    for i in range(n):
        swapped = False
        for j in range(n - i - 1):
            if lst[j] > lst[j + 1]:
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
                swapped = True
        if not swapped:
            break   # already sorted — early exit
    return lst

# Time: O(n²) worst/average, O(n) best; Space: O(1)
```

